<?php $__env->startSection('content'); ?><div class="page-head"><div><div class="eyebrow">BUSINESS MANAGEMENT</div><h1><?php echo e($business->exists?'Edit':'Create'); ?> Business</h1></div></div><div class="panel form-panel"><form method="POST" action="<?php echo e($business->exists?route('businesses.update',$business):route('businesses.store')); ?>"><?php echo csrf_field(); ?> <?php if($business->exists): ?> <?php echo method_field('PUT'); ?> <?php endif; ?><div class="form-grid"><label>Business Name<input name="name" value="<?php echo e(old('name',$business->name)); ?>" required></label><label>Contact Person<input name="contact_person" value="<?php echo e(old('contact_person',$business->contact_person)); ?>"></label><label>Email<input name="email" type="email" value="<?php echo e(old('email',$business->email)); ?>"></label><label>Phone<input name="phone" value="<?php echo e(old('phone',$business->phone)); ?>"></label><label class="wide">Address<textarea name="address"><?php echo e(old('address',$business->address)); ?></textarea></label><label>GST / Tax Number<input name="tax_number" value="<?php echo e(old('tax_number',$business->tax_number)); ?>"></label><label>Status<select name="status"><option value="active" <?php if(old('status',$business->status)==='active'): echo 'selected'; endif; ?>>Active</option><option value="inactive" <?php if(old('status',$business->status)==='inactive'): echo 'selected'; endif; ?>>Inactive</option></select></label></div><div class="form-actions"><a class="btn secondary" href="<?php echo e(route('businesses.index')); ?>">Cancel</a><button class="btn primary">Save Business</button></div></form></div><?php $__env->stopSection(); ?>

